import json

chart = ['Cash', 'Sales', 'Rent']
given_journal = [
    {
      "id": "e1",
      "postings": [
        {
          "side": "debit",
          "account": "Cash",
          "amount": 1000
        },
        {
          "side": "credit",
          "account": "Sales",
          "amount": 1000
        }
      ]
    },
    {
      "id": "e2",
      "postings": [
        {
          "side": "debit",
          "account": "Rent",
          "amount": 300
        },
        {
          "side": "credit",
          "account": "Cash",
          "amount": 300
        }
      ]
    }
]
claimed_balances = {
    "Cash": 600
}

findings = []

for entry in given_journal:
    for posting in entry['postings']:
        if posting['account'] not in chart:
            findings.append({
                "type": "nonexistent_account",
                "locus": entry['id'],
                "detail": f"Account '{posting['account']}' not found in chart"
            })

for entry in given_journal:
    debits = sum(p['amount'] for p in entry['postings'] if p['side'] == 'debit')
    credits = sum(p['amount'] for p in entry['postings'] if p['side'] == 'credit')
    if debits != credits:
        findings.append({
            "type": "imbalance",
            "locus": entry['id'],
            "detail": f"Debits ({debits}) != Credits ({credits})"
        })

balance = {acc: 0 for acc in chart}
for entry in given_journal:
    for posting in entry['postings']:
        if posting['account'] in chart:
            if posting['side'] == 'debit':
                balance[posting['account']] += posting['amount']
            else:
                balance[posting['account']] -= posting['amount']

for account, claimed in claimed_balances.items():
    if account in balance and balance[account] != claimed:
        findings.append({
            "type": "balance_mismatch",
            "locus": account,
            "detail": f"Computed balance {balance[account]} does not match claimed {claimed}"
        })

derived = {
    "Cash.computed": balance['Cash']
}

print(json.dumps({"findings": findings, "derived": derived}))

